namespace Rekalogika\Analytics\Engine\Trigger;

use Doctrine\DBAL\Connection;

/**
 * Installs and drops the triggers generated by `TriggerSqlGenerator`
 * directly in the database. Meant for development. In production, put the
 * statements in a migration instead.
 */
final readonly class TriggerInstaller
{
    public function __construct(
        private TriggerSqlGenerator $generator,
    ) {}

    public function getGenerator(): TriggerSqlGenerator
    {
        return $this->generator;
    }

    /**
     * Drops the existing triggers, including the stale ones, and creates the
     * triggers of the current metadata, in a single transaction for each
     * entity manager.
     *
     * @return array<string,int> The number of statements executed, keyed by
     * the name of the entity manager.
     */
    public function install(): array
    {
        $createStatements = $this->generator->getCreateStatements();
        $dropStatements = $this->generator->getDropStatements();
        $result = [];

        foreach ($this->generator->getConnections() as $managerName => $connection) {
            $result[$managerName] = $this->execute($connection, [
                ...$dropStatements[$managerName] ?? [],
                ...$createStatements[$managerName] ?? [],
            ]);
        }

        return $result;
    }

    /**
     * Drops the triggers and their functions.
     *
     * @return array<string,int> The number of statements executed, keyed by
     * the name of the entity manager.
     */
    public function drop(): array
    {
        $dropStatements = $this->generator->getDropStatements();
        $result = [];

        foreach ($this->generator->getConnections() as $managerName => $connection) {
            $result[$managerName] = $this->execute($connection, $dropStatements[$managerName] ?? []);
        }

        return $result;
    }

    /**
     * @param list<string> $statements
     */
    private function execute(Connection $connection, array $statements): int
    {
        $connection->transactional(static function (Connection $connection) use ($statements): void {
            foreach ($statements as $statement) {
                $connection->executeStatement($statement);
            }
        });

        return \count($statements);
    }
}
